  {"q": "仕入れ値の25%の利益を見込んで定価5250円をつけた。仕入れ値はいくらか。", "choices": ["4200円", "5050円", "4350円", "4050円"], "answer": 0, "exp": "仕入れ値×1.25=5250より、仕入れ値=4200円。"},
  {"q": "原価1800円の品物を定価2400円で売ったが、売れ残ったため定価の30%引きで販売した。このときの利益または損失はいくらか。", "choices": ["120円の損失", "270円の損失", "40円の損失", "420円の損失"], "answer": 0, "exp": "売価=2400×0.7=1680円。損失=120円。"},
  {"q": "原価4000円の品物を定価4500円で売ったが、売れ残ったため定価の10%引きで販売した。このときの利益または損失はいくらか。", "choices": ["50円の利益", "200円の利益", "1円の利益", "350円の利益"], "answer": 0, "exp": "売価=4500×0.9=4050円。利益=50円。"},
  {"q": "ある店で原価500円の商品を600個仕入れ、定価800円で売り始めたが、400個売れたところで残りを定価の50%引きで販売しすべて売り切った。総利益はいくらか。", "choices": ["100,000円", "115,000円", "85,000円", "120,000円"], "answer": 0, "exp": "400個×(800-500)=120,000円。残り200個×(400-500)=-20,000円。合計100,000円。"},
  {"q": "ある店で原価1200円の商品を300個仕入れ、定価1800円で売り始めたが、200個売れたところで残りを定価の30%引きで販売しすべて売り切った。総利益はいくらか。", "choices": ["126,000円", "141,000円", "111,000円", "120,000円"], "answer": 0, "exp": "200個×(1800-1200)=120,000円。残り100個×(1260-1200)=6,000円。合計126,000円。"},
  {"q": "ある商品を定価の20%引きで売ったところ、利益は原価の8%になった。定価は原価の何倍か。", "choices": ["1.35倍", "1.41倍", "1.29倍", "1.08倍"], "answer": 0, "exp": "定価×0.8=原価×1.08より、定価=原価×1.35倍。"},
  {"q": "ある商品を定価の30%引きで売ったところ、利益は原価の17%になった。定価は原価の何倍か。", "choices": ["1.671倍", "1.731倍", "1.611倍", "1.17倍"], "answer": 0, "exp": "定価×0.7=原価×1.17より、定価=原価×1.671倍。"},
  {"q": "原価2500円の商品に4割の利益を見込んで定価をつけたが、売れなかったため定価の1割5分引きで販売した。売価はいくらか。", "choices": ["2975円", "3400円", "2500円", "3150円"], "answer": 0, "exp": "定価=2500×1.4=3500円。売価=3500×0.85=2975円。"},
  {"q": "ある商品の売価が2400円で、これは原価の1.2倍である。原価はいくらか。", "choices": ["2000円", "2200円", "1800円", "2100円"], "answer": 0, "exp": "原価=2400÷1.2=2000円。"},
  {"q": "原価3600円の商品に定価をつけて売ったところ、利益は900円だった。定価は原価の何倍か。", "choices": ["1.25倍", "1.3倍", "1.2倍", "1.35倍"], "answer": 0, "exp": "定価=3600+900=4500円。4500÷3600=1.25倍。"},
  {"q": "ある商品を定価3000円の2割引きで売ったところ、原価に対して200円の利益が出た。原価はいくらか。", "choices": ["2200円", "2400円", "2000円", "2600円"], "answer": 0, "exp": "売価=3000×0.8=2400円。原価=2400-200=2200円。"}
